export function marketingCopy(text: string, locale: "en" | "zh"): string {
  if (locale === "en") return text;
  const taskError = /^(Missing|Invalid) task ([A-Z]+-\d+)\. Your current work has not changed\.$/.exec(text);
  if (taskError) return `${taskError[1] === "Missing" ? "缺少任务" : "任务格式无效"} ${taskError[2]}。当前工作未改变。`;
  return marketingChineseCopy[text] ?? text;
}
